async function covivioDetail(url:string,lane:string){const r=await get(url),p=strip(r.text);if(!/\bHamburg\b/i.test(p)||!/Anzahl\s+Zimmer/i.test(p))return null;const am=p.match(/([A-ZÄÖÜ][A-Za-zÄÖÜäöüß .'-]+\s+\d+[a-zA-Z]?)\s*,\s*(2\d{4})\s+Hamburg/i),zip=am?.[2]||null;if(!zip||!HH_ZIPS.has(zip))return null;const objectId=clean(p.match(/Objekt.?nummer\s*\|?\s*([A-Z0-9.-]+)/i)?.[1]),warm=money(p.match(/Gesamtmiete\s*\|?\s*([\d.]+,\d{2})\s*€/i)?.[1]||p.match(/([\d.]+,\d{2})\s*€\s+Gesamtmiete/i)?.[1]),cold=money(p.match(/Mietpreis\s*\|?\s*([\d.]+,\d{2})\s*€/i)?.[1]);if(warm==null&&cold==null)return null;const title=clean(strip(r.text.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)?.[1]||''))||'Covivio Wohnungsangebot';return{id:objectId||new URL(r.url).pathname.split('/').filter(Boolean).at(-1),url:r.url,title,address:`${clean(am?.[1])}, ${zip} Hamburg`,postalCode:zip,warmRent:warm,coldRent:cold,rooms:num(p.match(/Anzahl\s+Zimmer\s*\|?\s*([\d.,]+)/i)?.[1]),area:num(p.match(/Fläche\s*\|?\s*([\d.,]+)\s*m/i)?.[1]),provider:'covivio',discovery_lane:lane,imageUrl:image(r.text,r.url)}}
function covivioIndexed(html:string){const out=new Set<string>();for(const re of [/covivio\.immo%2fobjekt%2fhamburg%2f([a-z0-9%_-]+)/gi,/covivio\.immo\/objekt\/hamburg\/([a-z0-9_-]+)/gi])for(const m of html.matchAll(re)){const slug=decodeURIComponent(m[1]).replace(/%2f.*$/i,'').replace(/\/$/,'');if(slug)out.add(`https://www.covivio.immo/objekt/hamburg/${slug}/`)}return[...out]}
async function covivio(lane:string){let urls:string[]=[];if(lane==='primary'){const r=await get('https://www.covivio.immo/wohnen/immobilie-finden/');urls=links(r.text,r.url,/covivio\.immo\/objekt\/hamburg\//i)}else{const qs=['site:covivio.immo/objekt/hamburg/ "Gesamtmiete" Hamburg','site:covivio.immo/objekt/hamburg/ Covivio Wohnung Hamburg'],rs=await Promise.allSettled(qs.map(q=>get(yahoo(q))));urls=rs.flatMap(x=>x.status==='fulfilled'?covivioIndexed(x.value.text):[])}urls=[...new Set(urls)].slice(0,12);const rs=await Promise.allSettled(urls.map(u=>covivioDetail(u,lane)));return unique(rs.flatMap(x=>x.status==='fulfilled'&&x.value?[x.value]:[]))}

async function swapDetail(url:string,lane:string){const r=await get(url),p=strip(r.text);if(!/\bHamburg\b/i.test(p))return null;const id=p.match(/Anzeigen-ID:\s*(\d+)/i)?.[1]||r.url.match(/\/tauschangebot\/(\d+)/)?.[1];if(!id)return null;const title=clean(strip(r.text.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)?.[1]||''))||`Tauschangebot ${id}`,d=p.match(/([\d.,]+)\s+Zimmer\s*[∙•]\s*([\d.,]+)\s*m²/i),published=p.match(/Veröffentlicht:\s*(\d{4}-\d{2}-\d{2})/i)?.[1]||null,cold=money(p.match(/Kaltmiete\s+(?:beträgt\s+)?([\d.]+(?:,\d{2})?)\s*€/i)?.[1]);let warm=money(p.match(/([\d.]+(?:,\d{2})?)\s*EUR\/Monat/i)?.[1]);if(warm!=null&&((cold!=null&&warm<cold)||warm<250))warm=null;return{id,url:r.url,title,address:title,district:clean(p.match(/\b([A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]+),\s*Hamburg\b/i)?.[1]),warmRent:warm,coldRent:cold,rooms:num(d?.[1]),area:num(d?.[2]),propertyType:'Tauschwohnung',provider:'wohnungsswap',published_at:published,discovery_lane:lane,imageUrl:image(r.text,r.url)}}
