async function wohnungsswap(lane:string){let urls:string[]=[];if(lane==='primary'){const r=await get('https://www.wohnungsswap.de/');urls=links(r.text,r.url,/wohnungsswap\.de\/tauschangebot\/\d+/i)}else{const qs=['site:wohnungsswap.de/tauschangebot/ Hamburg Wohnungsswap','site:wohnungsswap.de/tauschangebot/ "Hamburg" "Veröffentlicht"'],rs=await Promise.allSettled(qs.map(q=>get(yahoo(q))));urls=rs.flatMap(x=>x.status==='fulfilled'?swapIndexed(x.value.text):[])}urls=[...new Set(urls)].slice(0,20);const rs=await Promise.allSettled(urls.map(u=>swapDetail(u,lane)));return unique(rs.flatMap(x=>x.status==='fulfilled'&&x.value?[x.value]:[]))}


